package com.leetcode.backend.controller;
import com.leetcode.backend.dto.*;import com.leetcode.backend.model.*;import com.leetcode.backend.repository.*;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;import java.util.stream.*;
@RestController @RequestMapping("/api/admin") public class AdminDetailAnalyticsController{
 final UserRepository users;final ProblemRepository problems;final SubmissionRepository submissions;final TestCaseRepository tests;
 AdminDetailAnalyticsController(UserRepository u,ProblemRepository p,SubmissionRepository s,TestCaseRepository t){users=u;problems=p;submissions=s;tests=t;}
 @GetMapping("/users/{id}/analytics") public AdminUserAnalyticsResponse user(@PathVariable Long id){User u=users.findById(id).orElseThrow();List<Submission>x=submissions.findByUserIdOrderBySubmittedAtDesc(id);Set<Long>solved=x.stream().filter(s->"ACCEPTED".equals(s.getStatus())).map(s->s.getProblem().getId()).collect(Collectors.toSet());long accepted=x.stream().filter(s->"ACCEPTED".equals(s.getStatus())).count();Map<String,Long>langs=x.stream().collect(Collectors.groupingBy(Submission::getLanguage,Collectors.counting()));List<Map<String,Object>>recent=x.stream().limit(10).map(s->Map.<String,Object>of("id",s.getId(),"problemTitle",s.getProblem().getTitle(),"status",s.getStatus(),"language",s.getLanguage(),"submittedAt",s.getSubmittedAt())).toList();return new AdminUserAnalyticsResponse(u.getId(),u.getUsername(),u.getRole().name(),x.isEmpty()?null:x.get(0).getSubmittedAt(),solved.size(),count(solved,"EASY"),count(solved,"MEDIUM"),count(solved,"HARD"),x.size(),accepted,x.isEmpty()?0:Math.round(accepted*100.0/x.size()),0,0,x.stream().map(s->s.getSubmittedAt().toLocalDate()).distinct().count(),langs,recent);}
 @GetMapping("/problems/{id}/analytics") public AdminProblemAnalyticsResponse problem(@PathVariable Long id){Problem p=problems.findById(id).orElseThrow();List<Submission>x=submissions.findByProblemIdOrderBySubmittedAtDesc(id);long a=x.stream().filter(s->"ACCEPTED".equals(s.getStatus())).count();return new AdminProblemAnalyticsResponse(id,p.getTitle(),p.getExecutionMode().name(),p.isActive(),x.size(),a,x.isEmpty()?0:Math.round(a*100.0/x.size()),x.stream().map(s->s.getUser().getId()).distinct().count(),x.stream().filter(s->"ACCEPTED".equals(s.getStatus())).map(s->s.getUser().getId()).distinct().count(),tests.findByProblemIdAndHiddenFalse(id).size(),tests.countByProblemIdAndHiddenTrue(id),x.stream().collect(Collectors.groupingBy(Submission::getStatus,Collectors.counting())),x.stream().collect(Collectors.groupingBy(Submission::getLanguage,Collectors.counting())));}
 long count(Set<Long>ids,String d){return ids.stream().map(problems::findById).flatMap(Optional::stream).filter(p->d.equalsIgnoreCase(p.getDifficulty())).count();}}
